<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api} from '../api/client'
import {useGuest} from '../stores/guest'
const guest=useGuest(),username=ref(''),password=ref(''),error=ref(''),busy=ref(false),label=ref(''),code=ref(''),status=ref<{enabled:boolean;provider:string;configured:boolean;requests_today:number;grants:{id:string;label:string;revoked:boolean;daily_limit:number;requests:number}[];invites:{id:string;label:string;redeemed:boolean;revoked:boolean}[]}|null>(null)
async function load(){if(guest.me?.admin)status.value=await api('/admin/status')}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function login(){await run(async()=>{await api('/admin/login','POST',{username:username.value,password:password.value});password.value='';await guest.refresh();await load()})}
async function invite(){await run(async()=>{const result=await api<{code:string}>('/admin/invites','POST',{label:label.value,days:7,daily_limit:30});code.value=result.code;label.value='';await load()})}
async function revoke(id:string,kind='grants'){await run(async()=>{await api(`/admin/${kind}/${id}/revoke`,'POST');await load()})}
async function toggle(){await run(async()=>{await api('/admin/inference','POST',{enabled:!status.value?.enabled});await load()})}
async function logout(){await run(async()=>{await api('/admin/logout','POST');await guest.refresh();status.value=null;code.value=''})}
onMounted(()=>run(load))
</script>
<template><span class="eyebrow">OWNER / ACCESS CONTROL</span><h1>{{guest.me?.admin?'Keep discussion intentional.':'Owner sign-in.'}}</h1><div v-if="error" class="error" role="alert">{{error}}</div><form v-if="!guest.me?.admin" class="panel login-form" @submit.prevent="login"><p>Admin accounts are created with the local interactive setup command. There is no default password.</p><label>Username<input v-model="username" autocomplete="username" maxlength="80"></label><label>Password<input v-model="password" type="password" autocomplete="current-password" maxlength="200"></label><button class="primary" :disabled="busy">Sign in →</button></form><template v-else-if="status"><section class="panel"><div class="section-heading"><h2>Provider & quotas</h2><button @click="logout" :disabled="busy">Sign out</button></div><p>Provider: {{status.provider}} · {{status.configured?'configured':'unconfigured'}} · {{status.enabled?'enabled':'disabled'}}</p><p>{{status.requests_today}} reserved requests today. Keys and endpoint settings are managed only on the server.</p><button @click="toggle" :disabled="busy">{{status.enabled?'Disable inference':'Enable configured inference'}}</button></section><section class="panel"><h2>Issue a single-use invitation</h2><p>Seven-day expiry; up to 30 requests per day. A label is for your records, not identity verification. Deliver codes out of band.</p><form @submit.prevent="invite"><label>Invitation label<input v-model="label" maxlength="80" placeholder="Hackathon visitor"></label><button :disabled="busy||!label">Create invitation</button></form><div v-if="code" class="notice"><strong>Shown once. Copy and deliver securely.</strong><code class="invitation-code">{{code}}</code><button @click="code=''">Hide code</button></div><div v-for="i in status.invites" :key="i.id" class="admin-row"><span>{{i.label}} · {{i.revoked?'revoked':i.redeemed?'redeemed':'unused'}}</span><button v-if="!i.revoked" @click="revoke(i.id,'invites')" :disabled="busy">Revoke</button></div></section><section class="panel"><h2>Active grants</h2><p v-if="!status.grants.length">No invitations redeemed yet.</p><div v-for="g in status.grants" :key="g.id" class="admin-row"><span>{{g.label}} · {{g.requests}} requests · {{g.daily_limit}} / day · {{g.revoked?'revoked':'active'}}</span><button v-if="!g.revoked" @click="revoke(g.id)" :disabled="busy">Revoke immediately</button></div></section></template></template>
